// GENERATED by tools/build_config.js - edit tools/config.html instead.
module.exports = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Logbook</title>\n<style>\n:root{--bg:#090b10;--card:#141922;--card2:#1b2230;--line:#262f3d;--text:#eef2f7;--mut:#8b97a8;--acc:#f7c948;--dim:#334052;--bad:#f87171;\n--c-movie:#ef5b5b;--c-tv:#38bdf8;--c-podcast:#a78bfa;--c-music:#34d399;--c-book:#fb923c;--c-song:#f472b6;--c-game:#a3e635;--c-recipe:#facc15;--c-other:#8b97a8;--c-all:#f7c948}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{margin:0;background:var(--bg);color:var(--text);font:16px/1.4 system-ui,-apple-system,Roboto,sans-serif;padding-bottom:96px}\nheader{position:sticky;top:0;background:linear-gradient(#10151e,var(--bg));padding:14px 16px 0;z-index:5;border-bottom:1px solid var(--line)}\n.brand{display:flex;align-items:center;gap:12px;margin-bottom:12px}\n.logo{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#f7c948,#f08a24);color:#2a1a00;display:flex;align-items:center;justify-content:center;font-size:22px;box-shadow:0 4px 14px rgba(247,201,72,.25)}\nh1{font-size:21px;margin:0;letter-spacing:.2px;line-height:1.1}\n.sub{color:var(--mut);font-size:13px}\n.tabs{display:flex;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:4px;margin-bottom:12px}\n.tab{flex:1;padding:8px 4px;text-align:center;border-radius:9px;color:var(--mut);font-weight:600;font-size:15px}\n.tab.on{background:var(--acc);color:#241800}\nmain{padding:14px 16px}\n[hidden]{display:none!important}\nbutton{font:inherit;border:0;border-radius:12px;padding:13px 16px;cursor:pointer}\n.primary{background:linear-gradient(135deg,#f7c948,#f0a22a);color:#241800;font-weight:700;box-shadow:0 6px 20px rgba(247,201,72,.25)}\n.ghost{background:var(--card2);color:var(--text);border:1px solid var(--line)}\n.danger{background:transparent;color:var(--bad);border:1px solid var(--bad)}\ninput,textarea{font:inherit;color:var(--text);background:var(--card2);border:1px solid var(--line);border-radius:12px;padding:11px 13px;width:100%}\ninput:focus,textarea:focus{outline:2px solid var(--acc);outline-offset:0}\nlabel,small{color:var(--mut);font-size:13px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:12px}\n.hint{color:var(--mut);font-size:14px;margin:6px 0}\n.chips{display:flex;gap:8px;overflow-x:auto;padding-bottom:12px;scrollbar-width:none}\n.chips::-webkit-scrollbar{display:none}\n.chip{flex:none;padding:7px 13px;border-radius:99px;border:1px solid var(--line);color:var(--mut);background:var(--card);font-size:14px;display:flex;align-items:center;gap:7px}\n.chip i{width:8px;height:8px;border-radius:50%;background:var(--cc,var(--acc));display:inline-block}\n.chip.on{background:var(--cc,var(--acc));color:#12100a;border-color:transparent;font-weight:700}\n.chip.on i{background:#12100a}\n.month{color:var(--mut);font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;margin:14px 2px 8px}\n.item{display:flex;gap:14px;align-items:stretch;background:var(--card);border:1px solid var(--line);border-left:4px solid var(--cc,var(--acc));border-radius:14px;padding:10px;margin-bottom:10px}\n.item:active{background:var(--card2)}\n.th{width:62px;height:90px;border-radius:9px;flex:none;background:#000 center/cover no-repeat;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700;letter-spacing:1px;box-shadow:0 3px 10px rgba(0,0,0,.45)}\n.th.sq{height:62px;align-self:center}\n.th.ph{background:linear-gradient(145deg,var(--cc),#10141c)}\n.item .t{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:4px}\n.item b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.25}\n.tag{align-self:flex-start;font-size:11px;font-weight:800;letter-spacing:.8px;text-transform:uppercase;color:var(--cc);background:color-mix(in srgb,var(--cc) 15%,transparent);padding:2px 8px;border-radius:99px}\n.rate{display:flex;align-items:center;gap:8px}\n.rate .n{color:var(--text);font-weight:700;font-size:14px}\n.stars{letter-spacing:2px;color:var(--acc);font-size:16px;white-space:nowrap}\n.stars i{font-style:normal;color:var(--dim)}\n.stars .hf,.big button.half{font-style:normal;background:linear-gradient(90deg,var(--acc) 50%,var(--dim) 50%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}\n.sval{text-align:center;color:var(--mut);margin:-2px 0 10px;font-size:14px}\n.row2{display:flex;justify-content:space-between;align-items:center}\n.hero{display:flex;gap:12px}\n.hero .box{flex:1;background:linear-gradient(160deg,var(--card2),var(--card));border:1px solid var(--line);border-radius:16px;padding:14px}\n.hero .num{font-size:34px;font-weight:800;line-height:1.05;color:var(--acc)}\n.hist{display:flex;align-items:flex-end;gap:5px;height:110px;margin:14px 0 6px}\n.hist div{flex:1;border-radius:5px 5px 2px 2px;background:linear-gradient(var(--acc),#c98f1a);min-height:3px;position:relative}\n.hist div.z{background:var(--dim)}\n.hist span{position:absolute;top:-17px;left:0;right:0;text-align:center;font-size:11px;color:var(--mut)}\n.axis{display:flex;gap:5px}.axis small{flex:1;text-align:center;font-size:10px}\n.cat{display:flex;gap:12px;align-items:center}\n.cat .dot{width:42px;height:42px;border-radius:13px;flex:none;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:11px;letter-spacing:.5px;color:#12100a;background:var(--cc)}\n.cat .grow{flex:1;min-width:0}\n.meter{height:8px;border-radius:99px;background:var(--dim);overflow:hidden;margin-top:8px}\n.meter>div{height:100%;border-radius:99px;background:var(--cc)}\n.sheet{position:fixed;left:0;right:0;bottom:0;background:var(--card);border-top:1px solid var(--line);border-radius:22px 22px 0 0;padding:18px 16px calc(16px + env(safe-area-inset-bottom));z-index:20;box-shadow:0 -24px 50px rgba(0,0,0,.6)}\n.shead{display:flex;gap:14px;align-items:center;margin-bottom:6px}\n.shead .th{width:54px;height:78px}.shead .th.sq{height:54px}\n.shead b{flex:1;min-width:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.big{display:flex;justify-content:center;gap:4px;margin:10px 0}\n.big button{background:transparent;color:var(--dim);font-size:46px;padding:0 5px;line-height:1.1;border-radius:8px}\n.big button.on{color:var(--acc);text-shadow:0 0 18px rgba(247,201,72,.35)}\n.acts{display:flex;gap:8px}.acts button{flex:1}\nfooter{position:fixed;left:0;right:0;bottom:0;padding:14px 16px calc(14px + env(safe-area-inset-bottom));background:linear-gradient(transparent,var(--bg) 35%);z-index:10}\nfooter button{width:100%}\ntextarea{height:140px;font-size:13px;font-family:ui-monospace,Menlo,monospace}\n.seg{display:flex;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:4px;margin-bottom:12px}\n.seg button{flex:1;padding:8px 4px;border-radius:9px;background:transparent;color:var(--mut);font-weight:600;font-size:14px}\n.seg button.on{background:var(--card2);color:var(--acc);box-shadow:inset 0 0 0 1px var(--acc)}\n.dl{display:block;font-size:12px;color:var(--mut);margin-top:4px}\n.dl.up{color:#4ade80}.dl.down{color:#fb923c}\n.bars{display:flex;align-items:flex-end;gap:6px;height:120px;margin:22px 0 6px}\n.bars div{flex:1;border-radius:6px 6px 2px 2px;background:var(--acc);min-height:3px;position:relative}\n.bars div.z{background:var(--dim)}\n.bars div.now{background:#fff}\n.bars span{position:absolute;top:-17px;left:0;right:0;text-align:center;font-size:11px;color:var(--mut)}\n.cal{display:grid;grid-template-rows:repeat(7,1fr);grid-auto-flow:column;gap:3px;margin-top:6px}\n.cal i{aspect-ratio:1;border-radius:3px;background:var(--dim);display:block}\n.cal i.l1{background:#5b4a14}.cal i.l2{background:#8f7119}.cal i.l3{background:#c99a1f}.cal i.l4{background:#f7c948}.cal i.f{background:transparent}\n.cmon{position:relative;height:14px;font-size:10px;color:var(--mut)}\n.cmon span{position:absolute;top:0}\n.legend{display:flex;align-items:center;gap:4px;justify-content:flex-end;margin-top:8px;font-size:11px;color:var(--mut)}\n.legend i{width:11px;height:11px;border-radius:3px;display:inline-block;background:var(--dim)}\n.legend i.l1{background:#5b4a14}.legend i.l2{background:#8f7119}.legend i.l3{background:#c99a1f}.legend i.l4{background:#f7c948}\n.facts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}\n.facts div{background:var(--card2);border-radius:12px;padding:10px 12px}\n.facts b{display:block;font-size:20px;color:var(--text)}\n.insight{margin-top:10px;font-size:14px;color:var(--mut)}.insight b{color:var(--acc)}\n.pick{display:flex;align-items:center;gap:12px;border-left:4px solid var(--cc,var(--acc));background:var(--card2);border-radius:10px;padding:10px 12px;margin-top:8px}\n.pick b{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pick .stars{font-size:14px;letter-spacing:1px}\n.pick.low{border-left-color:#fb923c}\n.kv{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--line);font-size:14px}\n.kv:last-child{border-bottom:0}.kv span:first-child{color:var(--mut)}\n.search{margin-bottom:12px}\n.seg{position:sticky;top:var(--hh,120px);z-index:4;box-shadow:0 8px 12px -6px var(--bg)}\ndetails.card>summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center}\ndetails.card>summary::-webkit-details-marker{display:none}\ndetails.card>summary::after{content:'\\25BE';color:var(--mut)}\ndetails.card[open]>summary::after{content:'\\25B4'}\n.recap{background:linear-gradient(160deg,#241a05,var(--card));border-color:#4a3910}\n.recap .big2{font-size:30px;font-weight:800;color:var(--acc);line-height:1.1}\n.recap p{margin:6px 0}\n.steps{margin:8px 0 4px;padding-left:20px;color:var(--text);font-size:14px;line-height:1.5}\n.steps li{margin:6px 0}.steps b{color:var(--acc)}\n.chk{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}\n.chk:last-child{border-bottom:0}\n.pill{font-size:12px;font-weight:700;padding:3px 10px;border-radius:99px;background:var(--dim);color:var(--mut);white-space:nowrap}\n.pill.ok{background:#14532d;color:#86efac}.pill.need{background:#4a3910;color:var(--acc)}\n.setup summary{font-weight:600;cursor:pointer;padding:6px 0;color:var(--acc)}\n.setup[open] summary{margin-bottom:4px}\n.fine{color:var(--mut);font-size:12px;margin:10px 0 0}\n.fine a{color:var(--mut)}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"brand\"><div class=\"logo\">★</div><div><h1>Logbook</h1><div class=\"sub\" id=\"subtitle\"></div></div></div>\n  <div class=\"tabs\"><div class=\"tab on\" id=\"t1\">History</div><div class=\"tab\" id=\"t2\">Stats</div><div class=\"tab\" id=\"t3\">Settings</div></div>\n</header>\n\n<main>\n  <section id=\"v1\">\n    <input class=\"search\" id=\"q\" type=\"search\" placeholder=\"Search your ratings\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n    <div class=\"chips\" id=\"chips\"></div>\n    <div id=\"list\"></div>\n    <p class=\"hint\" id=\"empty\" hidden>Nothing here yet. Say a title on your watch and rate it; it shows up here.</p>\n    <p class=\"hint\" id=\"more\" hidden></p>\n  </section>\n\n  <section id=\"v2\" hidden></section>\n\n  <section id=\"v3\" hidden>\n    <div class=\"card\" id=\"welcome\">\n      <b>Welcome to Logbook</b>\n      <p class=\"hint\">Say what you watched, read, played or ate on your watch, give it stars, and this page keeps your history and stats. Only the first item below is needed. The rest are optional.</p>\n      <div class=\"chk\"><span>1. TMDB key (movies and TV)</span><span class=\"pill need\" id=\"p_tk\">Needed</span></div>\n      <div class=\"chk\"><span>2. Letterboxd (marks films you've seen)</span><span class=\"pill\" id=\"p_lb\">Optional</span></div>\n      <div class=\"chk\"><span>3. Google Sheets backup</span><span class=\"pill\" id=\"p_gs\">Optional</span></div>\n      <p class=\"hint\">Podcasts, albums, songs, books, games, recipes and \"Anything\" work with no setup. After you change something here, tap <b>Save</b> at the bottom.</p>\n    </div>\n\n    <div class=\"card\">\n      <b>1. TMDB key (movies and TV)</b>\n      <p class=\"hint\">Movie and TV search comes from The Movie Database, which gives out a free key for personal use. It takes about five minutes.</p>\n      <details class=\"setup\" id=\"tmdbsteps\"><summary>How to get your key</summary>\n        <ol class=\"steps\">\n          <li>On a computer or your phone's browser, go to <b>themoviedb.org</b> and create a free account. Confirm the email they send.</li>\n          <li>Open your profile menu, then <b>Settings</b>, then <b>API</b>, and choose to request a key. Pick <b>Developer</b>, accept the terms, and fill in the form (personal use, and say it's a watch app for logging what you watch).</li>\n          <li>On the API page, copy the <b>API Read Access Token</b> (the long one) or the <b>API Key</b>. Either works.</li>\n          <li>Paste it in the box below and tap <b>Save</b>.</li>\n        </ol>\n      </details>\n      <input id=\"tk\" placeholder=\"Paste TMDB API key or read access token\" autocapitalize=\"off\" autocomplete=\"off\" spellcheck=\"false\">\n      <p class=\"fine\">This product uses the TMDB API but is not endorsed or certified by TMDB.</p>\n    </div>\n    <div class=\"card\">\n      <b>Letterboxd</b>\n      <p class=\"hint\">Optional. Search on the watch will mark films you've already seen (for example \"seen 4.5\"), and your recent Letterboxd ratings are added to your log.</p>\n      <details class=\"setup\"><summary>How to set this up</summary>\n        <ol class=\"steps\">\n          <li>Your username is the last part of your profile address: letterboxd.com/<b>yourname</b>. Type it in the box below, without the @.</li>\n          <li>Your profile has to be <b>public</b> for this to work. In Letterboxd, open Settings, then Profile, and make sure your profile isn't private.</li>\n          <li>Tap <b>Save</b>. Your latest diary entries are read when you save and each time the app opens (at most every few hours). The feed only covers recent entries.</li>\n          <li><b>For your full history:</b> on letterboxd.com choose Settings, then Data, then Export your data, and open the file you download. Open <b>ratings.csv</b> (or <b>watched.csv</b> to include films you didn't rate) in any text editor, select all, copy, and paste it into the second box. Tap Save. You can do this in parts if you have thousands of films.</li>\n        </ol>\n        <p class=\"hint\">Letterboxd doesn't let apps write back, so this only works in one direction: Letterboxd to Logbook.</p>\n      </details>\n      <input id=\"lbu\" placeholder=\"Letterboxd username\" autocapitalize=\"off\" autocomplete=\"off\" spellcheck=\"false\">\n      <p class=\"hint\" id=\"lbs\"></p>\n      <textarea id=\"lbcsv\" placeholder=\"Optional: paste your Letterboxd export (ratings.csv or watched.csv)\"></textarea>\n      <p class=\"hint\" id=\"lbcnt\"></p>\n      <label class=\"hint\" style=\"display:flex;gap:8px;align-items:flex-start;margin:6px 0\"><input type=\"checkbox\" id=\"lbhist\" checked style=\"margin-top:2px\"> <span>Also add my rated films to my history and stats, dated by when I watched them.</span></label>\n      <label class=\"hint\" style=\"display:flex;gap:8px;align-items:flex-start;margin:6px 0\"><input type=\"checkbox\" id=\"lbsheet\" checked style=\"margin-top:2px\"> <span>Also send them to my Google Sheet (needs Sheets set up below).</span></label>\n      <div style=\"height:8px\"></div>\n      <button class=\"ghost\" id=\"lbsync\" style=\"width:100%\">Sync when I save</button>\n    </div>\n    <div class=\"card\" id=\"favcard\" hidden>\n      <b>Favorites</b>\n      <p class=\"hint\">Hold the middle button on a show, podcast or album in the watch's results to pin it. Hold it on a favorite in the full menu to remove it.</p>\n      <div id=\"favlist\"></div>\n    </div>\n    <div class=\"card\">\n      <b>Using Logbook on your watch</b>\n      <details class=\"setup\"><summary>Buttons and gestures</summary>\n        <ol class=\"steps\">\n          <li><b>Home</b> shows today. <b>Middle</b> = say what you watched, read, played or ate. <b>Up</b> = your stats (<b>hold Up</b> = Reflect). <b>Down</b> = the full menu (favorites, continue, log by kind, recent, reflect, bookmarks).</li>\n          <li><b>Reflect</b> lists your latest ratings. Pick one to see what you wrote about it, add a note, bookmark it or change its rating. Or hold the middle button on a rating to say a note right away.</li>\n          <li>Pick a result, set the stars with Up and Down (the left half of a star is a half), and press <b>Select</b> to save.</li>\n          <li>After picking \"Anything\", you can say a category (restaurant, coffee...) so it's filed separately.</li>\n          <li><b>Hold the middle button</b> on a result or on the rating screen to say a bookmark: \"26 minutes in, great interview\". Hold it on a show, podcast or album to pin it to favorites, and on Home to re-rate your latest item.</li>\n          <li>Open Logbook from your quick launch button to start listening right away.</li>\n        </ol>\n      </details>\n    </div>\n    <div class=\"card\">\n      <b>Everything else</b>\n      <p class=\"hint\">Podcasts, albums and songs use Apple's free search, books use Google Books and Open Library, games use Steam's store search, and recipes use TheMealDB. No keys needed. \"Anything\" on the watch takes whatever you say as the title, then asks for a category (restaurant, coffee...). That category is what shows in your Google Sheet.</p>\n    </div>\n    <div class=\"card\">\n      <b>Export</b>\n      <p class=\"hint\">Copy this into a spreadsheet. It covers the ratings shown on this page.</p>\n      <textarea id=\"csv\" readonly></textarea>\n      <div style=\"height:8px\"></div>\n      <button class=\"ghost\" id=\"copy\" style=\"width:100%\">Select all</button>\n    </div>\n  </section>\n</main>\n\n<div class=\"sheet\" id=\"sheet\" hidden>\n  <div class=\"shead\"><span id=\"sart\"></span><b id=\"sttl\"></b><button class=\"ghost\" id=\"sclose\">Done</button></div>\n  <div class=\"big\" id=\"sbig\"></div>\n  <div class=\"sval\" id=\"sval\"></div>\n  <div class=\"acts\"><button class=\"danger\" id=\"sdel\">Delete rating</button></div>\n</div>\n\n<footer><button class=\"primary\" id=\"done\">Save</button></footer>\n\n<script>\nvar INIT = /*INIT*/null;\nINIT = INIT || {};\n(function () {\n  var CATS = [['all', 'All'], ['movie', 'Movies'], ['tv', 'TV'], ['podcast', 'Podcasts'], ['music', 'Albums'], ['song', 'Songs'], ['book', 'Books'], ['game', 'Games'], ['recipe', 'Recipes'], ['other', 'Other']];\n  var CAT_NAME = { movie: 'Movie', tv: 'TV', podcast: 'Podcast', music: 'Album', book: 'Book', song: 'Song', game: 'Game', recipe: 'Recipe', other: 'Other' };\n  var CAT_SHORT = { movie: 'FILM', tv: 'TV', podcast: 'POD', music: 'ALBUM', book: 'BOOK', song: 'SONG', game: 'GAME', recipe: 'FOOD', other: 'ANY' };\n  var log = (INIT.log || []).slice().sort(function (a, b) { return b.ts - a.ts; });\n  var edits = {}, deletes = [], markDeletes = [], favDeletes = [], lbSyncReq = false;\n  var marks = (INIT.marks || []).slice();\n  var favs = (INIT.favs || []).slice();\n  var filter = 'all';\n  var current = null;\n\n  function $(id) { return document.getElementById(id); }\n  function esc(s) {\n    return String(s == null ? '' : s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n  function starsHtml(n) {\n    var h = '';\n    for (var i = 1; i <= 5; i++) h += n >= i ? '★' : (n >= i - 0.5 ? '<span class=\"hf\">★</span>' : '<i>★</i>');\n    return '<span class=\"stars\">' + h + '</span>';\n  }\n  function dateOf(ts) {\n    try { return new Date(ts).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); } catch (e) { return ''; }\n  }\n  function timeOf(ts) {\n    try { return new Date(ts).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }); } catch (e) { return ''; }\n  }\n  function catLabel(r) { return r.tag ? r.tag : (CAT_NAME[r.cat] || ''); }\n  function tagList() {\n    var seen = {}, out = [];\n    log.forEach(function (r) { if (r.tag && !seen[r.tag]) { seen[r.tag] = 1; out.push(r.tag); } });\n    return out.sort();\n  }\n  function shown() {\n    var q = ($('q').value || '').toLowerCase().replace(/^\\s+|\\s+$/g, '');\n    return log.filter(function (r) {\n      var okCat = filter === 'all' || (filter.indexOf('tag:') === 0 ? r.tag === filter.slice(4) : r.cat === filter);\n      return okCat && (!q || String(r.title).toLowerCase().indexOf(q) >= 0);\n    });\n  }\n\n  // ------------------------------------------------------------ history\n  function renderChips() {\n    var h = '';\n    if (marks.length) h += '<button class=\"chip' + (filter === 'marks' ? ' on' : '') + '\" data-f=\"marks\" style=\"--cc:var(--c-book)\"><i></i>Bookmarks and notes ' + marks.length + '</button>';\n    CATS.forEach(function (c) {\n      var n = c[0] === 'all' ? log.length : log.filter(function (r) { return r.cat === c[0]; }).length;\n      h += '<button class=\"chip' + (filter === c[0] ? ' on' : '') + '\" data-f=\"' + c[0] + '\" style=\"--cc:var(--c-' + c[0] + ')\"><i></i>' + c[1] + ' ' + n + '</button>';\n    });\n    tagList().forEach(function (t) {\n      var n = log.filter(function (r) { return r.tag === t; }).length;\n      h += '<button class=\"chip' + (filter === 'tag:' + t ? ' on' : '') + '\" data-f=\"tag:' + esc(t) + '\" style=\"--cc:var(--c-other)\"><i></i>' + esc(t) + ' ' + n + '</button>';\n    });\n    $('chips').innerHTML = h;\n  }\n\n  function thumb(r, big) {\n    var sq = ({ music: 1, podcast: 1, song: 1, game: 1, recipe: 1 })[r.cat] ? ' sq' : '';\n    if (r.art) return '<div class=\"th' + sq + '\" style=\"background-image:url(\\'' + esc(r.art) + '\\')\"></div>';\n    return '<div class=\"th ph' + sq + '\">' + esc(CAT_SHORT[r.cat] || '?') + '</div>';\n  }\n  function monthOf(ts) {\n    try { return new Date(ts).toLocaleDateString(undefined, { month: 'long', year: 'numeric' }); } catch (e) { return ''; }\n  }\n\n  function renderList() {\n    renderChips();\n    $('subtitle').textContent = log.length + (log.length === 1 ? ' rating' : ' ratings') + ' logged';\n    if (filter === 'marks') { $('subtitle').textContent = marks.length + (marks.length === 1 ? ' bookmark or note' : ' bookmarks and notes'); renderMarks(); return; }\n    var rows = shown();\n    var h = '', last = '';\n    rows.forEach(function (r) {\n      var m = monthOf(r.ts);\n      if (m !== last) { h += '<div class=\"month\">' + esc(m) + '</div>'; last = m; }\n      h += '<div class=\"item\" data-ref=\"' + esc(r.ref) + '\" style=\"--cc:var(--c-' + esc(r.cat) + ')\">' + thumb(r) +\n        '<div class=\"t\"><span class=\"tag\">' + esc(catLabel(r)) + '</span><b>' + esc(r.title) + '</b>' +\n        '<div class=\"rate\">' + starsHtml(r.stars) + '<span class=\"n\">' + r.stars + '</span></div><small>' + esc(dateOf(r.ts)) + '</small></div></div>';\n    });\n    $('list').innerHTML = h;\n    $('empty').hidden = log.length > 0 || !!$('q').value;\n    if (!rows.length && log.length) $('list').innerHTML = '<p class=\"hint\">No ratings match.</p>';\n    var total = INIT.total || log.length;\n    $('more').hidden = !(total > log.length + deletes.length && log.length > 0);\n    $('more').textContent = 'Showing your latest ' + log.length + ' of ' + total + ' ratings.';\n  }\n\n  function renderMarks() {\n    var q = ($('q').value || '').toLowerCase().replace(/^\\s+|\\s+$/g, '');\n    var list = marks.filter(function (mk) { return !q || [mk.title, mk.note, mk.track, mk.pos].join(' ').toLowerCase().indexOf(q) >= 0; });\n    var h = '<div class=\"month\">Bookmarks and notes</div>';\n    if (!list.length) h += '<p class=\"hint\">' + (q ? 'No bookmarks match.' : 'Nothing yet.') + '</p>';\n    list.forEach(function (mk) {\n      var kind = mk.marked ? 'Mark' : (mk.pos || !mk.note ? 'Bookmark' : 'Note');\n      h += '<div class=\"item\" style=\"--cc:var(--c-' + esc(mk.cat) + ')\">' + thumb(mk) +\n        '<div class=\"t\"><span class=\"tag\">' + esc((CAT_NAME[mk.cat] || '') + ' \\u00b7 ' + kind) + '</span><b>' + esc(mk.title) + '</b>' +\n        (mk.track ? '<div class=\"rate\"><span class=\"n\">\\u266a ' + esc(mk.track) + '</span></div>' : '') +\n        (mk.pos ? '<div class=\"rate\"><span class=\"n\">@ ' + esc(mk.pos) + '</span></div>' : '') +\n        (mk.note ? '<small style=\"color:var(--text)\">' + esc(mk.note) + '</small>' : '') +\n        '<small>' + esc(dateOf(mk.ts) + ' \\u00b7 ' + timeOf(mk.ts)) + '</small></div>' +\n        '<button class=\"danger\" data-md=\"' + mk.ts + '\" style=\"align-self:center;padding:8px 12px\">Delete</button></div>';\n    });\n    $('list').innerHTML = h;\n    $('empty').hidden = true;\n    $('more').hidden = !(INIT.marksTotal > marks.length + markDeletes.length);\n    $('more').textContent = 'Showing your latest ' + marks.length + ' bookmarks.';\n  }\n\n  function renderFavs() {\n    $('favcard').hidden = !favs.length;\n    $('favlist').innerHTML = favs.map(function (f) {\n      return '<div class=\"kv\"><span style=\"color:var(--text)\">' + esc(f.title) + '</span><button class=\"danger\" data-fd=\"' + esc(f.ref) + '\" style=\"padding:6px 12px\">Remove</button></div>';\n    }).join('');\n  }\n\n  // Letterboxd export (ratings.csv / watched.csv) -> \"Name|Year|Rating\" lines\n  function csvRows(text) {\n    var rows = [], row = [], cell = '', q = false, i, c;\n    text = String(text || '').replace(/\\r/g, '').replace(/^\\uFEFF/, '');\n    var first = text.split('\\n')[0] || '';\n    var sep = ',';                       // a paste can arrive tab- or semicolon-separated\n    if (first.split('\\t').length > first.split(',').length) sep = '\\t';\n    else if (first.split(';').length > first.split(',').length) sep = ';';\n    for (i = 0; i < text.length; i++) {\n      c = text.charAt(i);\n      if (q) {\n        if (c === '\"') { if (text.charAt(i + 1) === '\"') { cell += '\"'; i++; } else q = false; }\n        else cell += c;\n      } else if (c === '\"') q = true;\n      else if (c === sep) { row.push(cell); cell = ''; }\n      else if (c === '\\n') { row.push(cell); rows.push(row); row = []; cell = ''; }\n      else cell += c;\n    }\n    if (cell || row.length) { row.push(cell); rows.push(row); }\n    return rows;\n  }\n  function lbRows() {\n    var rows = csvRows($('lbcsv').value);\n    if (rows.length < 2) return [];\n    var head = rows[0].map(function (h) { return h.toLowerCase().replace(/^\\s+|\\s+$/g, ''); });\n    var ni = head.indexOf('name'), yi = head.indexOf('year'), ri = head.indexOf('rating'), di = head.indexOf('date');\n    if (ni < 0 || yi < 0) return [];\n    var out = [];\n    rows.slice(1, 801).forEach(function (r) {\n      if (r[ni]) out.push(r[ni].replace(/\\|/g, ' ') + '|' + (r[yi] || '') + '|' + (ri >= 0 ? (r[ri] || '') : '') + '|' + (di >= 0 ? (r[di] || '') : ''));\n    });\n    return out;\n  }\n\n  function lbCount() {\n    var raw = $('lbcsv').value, el = $('lbcnt');\n    if (!raw.replace(/\\s+/g, '')) { el.textContent = ''; return; }\n    var n = lbRows().length;\n    el.textContent = n ? 'Ready: ' + n + ' films found. Tap Save to import.'\n                        : 'No films found. The first line needs Name and Year columns.';\n  }\n\n  function find(ref) {\n    for (var i = 0; i < log.length; i++) if (log[i].ref === ref) return log[i];\n    return null;\n  }\n\n  function openSheet(ref) {\n    var r = find(ref);\n    if (!r) return;\n    current = r;\n    $('sttl').textContent = r.title;\n    $('sart').innerHTML = thumb(r);\n    $('sheet').style.setProperty('--cc', 'var(--c-' + r.cat + ')');\n    drawBig();\n    $('sheet').hidden = false;\n  }\n  function drawBig() {\n    var h = '';\n    for (var i = 1; i <= 5; i++) h += '<button data-s=\"' + i + '\" class=\"' + (current.stars >= i ? 'on' : (current.stars >= i - 0.5 ? 'half' : '')) + '\" aria-label=\"' + i + ' stars\">★</button>';\n    $('sbig').innerHTML = h;\n    $('sval').textContent = current.stars + ' / 5  ·  tap the left half of a star for a half';\n  }\n  function closeSheet() { $('sheet').hidden = true; current = null; renderList(); renderStats(); renderCsv(); }\n\n  // ------------------------------------------------------------ stats\n  // The phone computes these from your whole log (see stats.js), so they cover more\n  // than the recent ratings listed under History.\n  var RANGES = [['w', 'Week'], ['m', 'Month'], ['y', 'Year'], ['a', 'All']];\n  var BAR_TITLE = { w: 'Rated per day', m: 'Rated per 5 days', y: 'Rated per month', a: 'Rated per quarter' };\n  var PREV_NAME = { w: 'the 7 days before', m: 'the 30 days before', y: 'the year before' };\n  var CAT_PLURAL = { movie: 'Movies', tv: 'TV', podcast: 'Podcasts', music: 'Albums', book: 'Books', song: 'Songs', game: 'Games', recipe: 'Recipes', other: 'Other' };\n  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\n  var LETTER_CAT = { m: 'movie', t: 'tv', p: 'podcast', a: 'music', b: 'book', s: 'song', g: 'game', r: 'recipe', x: 'other' };\n  var range = 'm';\n  var calOpen = true;\n\n  function catOfRef(ref) { return LETTER_CAT[String(ref).charAt(0)] || 'other'; }\n\n  function deltaHtml(R) {\n    if (R.prevN === null || R.prevN === undefined) return '';\n    var d = R.n - R.prevN;\n    var cls = d > 0 ? 'up' : (d < 0 ? 'down' : '');\n    var txt = d > 0 ? '+' + d : (d < 0 ? String(d) : 'same');\n    return '<span class=\"dl ' + cls + '\">' + txt + ' vs ' + PREV_NAME[range] + '</span>';\n  }\n  function avgDelta(R) {\n    if (R.prevN === null || R.prevN === undefined || !R.prevN || !R.n) return '';\n    var d = Math.round((R.avg - R.prevAvg) * 10) / 10;\n    if (!d) return '<span class=\"dl\">same average</span>';\n    return '<span class=\"dl ' + (d > 0 ? 'up' : 'down') + '\">' + (d > 0 ? '+' : '') + d.toFixed(1) + ' vs ' + PREV_NAME[range] + '</span>';\n  }\n\n  function barsCard(R) {\n    var max = 1;\n    R.bars.forEach(function (b) { if (b.n > max) max = b.n; });\n    var h = '<div class=\"card\"><b>' + BAR_TITLE[range] + '</b><div class=\"bars\">';\n    var ax = '';\n    R.bars.forEach(function (b) {\n      h += '<div class=\"' + (b.n ? (b.now ? 'now' : '') : 'z') + '\" style=\"height:' + (b.n ? Math.max(6, Math.round(b.n / max * 100)) : 3) + '%\">' + (b.n ? '<span>' + b.n + '</span>' : '') + '</div>';\n      ax += '<small style=\"flex:1;text-align:center;font-size:11px\">' + esc(b.l) + '</small>';\n    });\n    return h + '</div><div style=\"display:flex;gap:6px\">' + ax + '</div></div>';\n  }\n\n  function calendarCard(A) {\n    var cols = A.heatWide.length / 7, h = '<details class=\"card cald\"' + (calOpen ? ' open' : '') + '><summary><b>Last ' + cols + ' weeks</b></summary><div class=\"cmon\">';\n    var prev = -1;\n    for (var c = 0; c < cols; c++) {\n      var m = new Date((A.heatWideStart + c * 7) * 86400000).getUTCMonth();\n      if (m !== prev && c < cols - 1) h += '<span style=\"left:' + (c / cols * 100) + '%\">' + MONTHS[m] + '</span>';\n      prev = m;\n    }\n    h += '</div><div class=\"cal\" style=\"grid-template-columns:repeat(' + cols + ',1fr)\">';\n    var active = 0, shownDays = 0;\n    A.heatWide.forEach(function (l) {\n      if (l < 0) { h += '<i class=\"f\"></i>'; return; }\n      shownDays++;\n      if (l > 0) active++;\n      h += '<i class=\"' + (l ? 'l' + l : '') + '\"></i>';\n    });\n    h += '</div><div class=\"legend\">Less <i></i><i class=\"l1\"></i><i class=\"l2\"></i><i class=\"l3\"></i><i class=\"l4\"></i> More</div>';\n    h += '<div class=\"facts\"><div><small>Current streak</small><b>' + A.streak + (A.streak === 1 ? ' day' : ' days') + '</b></div>' +\n      '<div><small>Best streak</small><b>' + A.best + (A.best === 1 ? ' day' : ' days') + '</b></div>' +\n      '<div><small>Active days</small><b>' + active + ' of ' + shownDays + '</b></div>' +\n      '<div><small>Rated today</small><b>' + (A.todayN || 0) + '</b></div></div></details>';\n    return h;\n  }\n\n  function kindsCard(R) {\n    if (!R.kinds.length) return '';\n    var h = '';\n    R.kinds.forEach(function (k) {\n      h += '<div class=\"card cat\" style=\"--cc:var(--c-' + k.cat + ')\"><div class=\"dot\">' + CAT_SHORT[k.cat] + '</div><div class=\"grow\">' +\n        '<div class=\"row2\"><b>' + (CAT_PLURAL[k.cat] || k.cat) + '</b><small>' + k.n + ' rated · avg ' + k.avg.toFixed(1) + '</small></div>' +\n        '<div class=\"meter\"><div style=\"width:' + Math.round(k.avg / 5 * 100) + '%\"></div></div></div></div>';\n    });\n    return '<div class=\"month\">By kind</div>' + h;\n  }\n\n  function tagsCard(R) {\n    if (!R.tags || !R.tags.length) return '';\n    var h = '<div class=\"card\"><b>Anything, by category</b>';\n    R.tags.forEach(function (t) {\n      h += '<div class=\"kv\"><span style=\"color:var(--text)\">' + esc(t.tag) + '</span><span>' + t.n + ' rated · avg ' + t.avg.toFixed(1) + '</span></div>';\n    });\n    return h + '</div>';\n  }\n\n  function histCard(R) {\n    var max = Math.max.apply(null, R.hist.concat([1]));\n    var h = '<div class=\"card\"><b>How you rate</b><div class=\"hist\">', ax = '';\n    for (var k = 1; k <= 10; k++) {\n      var n = R.hist[k - 1];\n      h += '<div class=\"' + (n ? '' : 'z') + '\" style=\"height:' + (n ? Math.max(6, Math.round(n / max * 100)) : 3) + '%\">' + (n ? '<span>' + n + '</span>' : '') + '</div>';\n      ax += '<small>' + (k % 2 ? '' : (k / 2)) + '</small>';\n    }\n    h += '</div><div class=\"axis\">' + ax + '</div>';\n    if (R.n) h += '<div class=\"insight\"><b>' + esc(R.common) + '</b> · ' + esc(R.tone) + '<br>' + R.lovedShare + '% of what you rate gets 4 stars or more.</div>';\n    return h + '</div>';\n  }\n\n  function pickRow(p, low) {\n    return '<div class=\"pick' + (low ? ' low' : '') + '\" style=\"--cc:var(--c-' + catOfRef(p.ref) + ')\"><b>' + esc(p.title) + '</b>' + starsHtml(p.stars) + '</div>';\n  }\n  function highlightsCard(R) {\n    if (!R.top.length) return '';\n    var h = '<div class=\"card\"><b>Top picks</b>';\n    R.top.forEach(function (p) { h += pickRow(p, false); });\n    if (R.low) h += '<div style=\"height:10px\"></div><b>Lowest rated</b>' + pickRow(R.low, true);\n    return h + '</div>';\n  }\n\n  var FULL_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];\n  function recapText(S) {\n    var Y = S.ranges.y, A = S.activity;\n    if (!Y.n) return '';\n    var busiest = -1, bn = 0, nowM = new Date().getMonth();\n    Y.bars.forEach(function (b, i) { if (b.n > bn) { bn = b.n; busiest = i; } });\n    var parts = ['My year in Logbook: ' + Y.n + ' ratings, averaging ' + Y.avg.toFixed(1) + ' stars.'];\n    if (Y.kinds.length) parts.push('Most logged: ' + (CAT_PLURAL[Y.kinds[0].cat] || Y.kinds[0].cat) + ' (' + Y.kinds[0].n + ').');\n    if (Y.top.length) parts.push('Top pick: ' + Y.top[0].title + '.');\n    if (busiest >= 0) parts.push('Busiest month: ' + FULL_MONTHS[((nowM - (Y.bars.length - 1 - busiest)) % 12 + 12) % 12] + ' (' + bn + ').');\n    if (A.best) parts.push('Best streak: ' + A.best + (A.best === 1 ? ' day.' : ' days.'));\n    return parts.join('\\n');\n  }\n  function recapCard(S) {\n    var t = recapText(S);\n    if (!t) return '';\n    var Y = S.ranges.y, lines = t.split('\\n');\n    return '<div class=\"card recap\"><b>Your year</b><div class=\"big2\">' + Y.n + ' ratings</div>' +\n      lines.slice(1).map(function (l) { return '<p>' + esc(l) + '</p>'; }).join('') +\n      '<button class=\"ghost\" data-copy=\"1\" style=\"width:100%;margin-top:8px\">Copy recap</button></div>';\n  }\n\n  function dataCard(S) {\n    var A = S.activity;\n    var first = A.first ? dateOf(A.first) : '-';\n    var sheets = INIT.sheetsUrl\n      ? 'On' + (INIT.sheetsPending ? ', ' + INIT.sheetsPending + ' waiting to send' : ', up to date')\n      : 'Not set up';\n    return '<div class=\"card\"><b>Your data</b>' +\n      '<div class=\"kv\"><span>Ratings stored on your phone</span><span>' + A.total + '</span></div>' +\n      '<div class=\"kv\"><span>First rating</span><span>' + esc(first) + '</span></div>' +\n      '<div class=\"kv\"><span>Google Sheets sync</span><span>' + esc(sheets) + '</span></div>' +\n      '<p class=\"hint\">Your phone keeps your latest 2,000 ratings. Turn on Google Sheets in Settings to keep everything.</p></div>';\n  }\n\n  function renderStats() {\n    var S = INIT.stats && INIT.stats.ranges ? INIT.stats : null;\n    if (!S || !S.activity.total) { $('v2').innerHTML = '<p class=\"hint\">Rate a few things and your stats appear here.</p>'; return; }\n    var R = S.ranges[range], A = S.activity;\n    A.todayN = S.today ? S.today.n : 0;\n    var h = '<div class=\"seg\">';\n    RANGES.forEach(function (r) { h += '<button data-r=\"' + r[0] + '\" class=\"' + (range === r[0] ? 'on' : '') + '\">' + r[1] + '</button>'; });\n    h += '</div>';\n    h += '<div class=\"hero\"><div class=\"box\"><small>Rated</small><div class=\"num\">' + R.n + '</div>' + deltaHtml(R) + '</div>' +\n      '<div class=\"box\"><small>Average</small><div class=\"num\">' + (R.n ? R.avg.toFixed(1) : '-') + '</div>' + (R.n ? starsHtml(Math.round(R.avg * 2) / 2) : '') + avgDelta(R) + '</div></div>';\n    h += '<div style=\"height:12px\"></div>';\n    if (R.n) {\n      h += barsCard(R);\n    } else {\n      h += '<p class=\"hint\">Nothing rated in this range yet.</p>';\n    }\n    h += calendarCard(A);\n    if (R.n) h += kindsCard(R) + tagsCard(R) + '<div style=\"height:2px\"></div>' + histCard(R) + highlightsCard(R);\n    h += recapCard(S) + dataCard(S);\n    if (Object.keys(edits).length || deletes.length) h += '<p class=\"hint\">Edits and deletions show up in these numbers after you save.</p>';\n    $('v2').innerHTML = h;\n  }\n\n  // ------------------------------------------------------------ export\n  function csvCell(v) { return '\"' + String(v == null ? '' : v).replace(/\"/g, '\"\"') + '\"'; }\n  function renderCsv() {\n    var lines = ['title,category,stars,date'];\n    log.forEach(function (r) {\n      lines.push([csvCell(r.title), csvCell(catLabel(r)), r.stars, csvCell(new Date(r.ts).toISOString().slice(0, 10))].join(','));\n    });\n    $('csv').value = lines.join('\\n');\n  }\n\n  // ------------------------------------------------------------ wiring\n  function tab(n) {\n    for (var i = 1; i <= 3; i++) {\n      $('t' + i).classList.toggle('on', i === n);\n      $('v' + i).hidden = i !== n;\n    }\n    window.scrollTo(0, 0);\n  }\n  $('t1').onclick = function () { tab(1); };\n  $('t2').onclick = function () { tab(2); };\n  $('t3').onclick = function () { tab(3); };\n\n  document.addEventListener('click', function (e) {\n    var t = e.target;\n    while (t && t !== document && !(t.dataset && (t.dataset.f !== undefined || t.dataset.ref !== undefined || t.dataset.s !== undefined || t.dataset.r !== undefined || t.dataset.copy !== undefined || t.dataset.md !== undefined || t.dataset.fd !== undefined))) t = t.parentNode;\n    if (!t || t === document) return;\n    if (t.dataset.md !== undefined) {\n      var mts = +t.dataset.md;\n      markDeletes.push(mts);\n      marks = marks.filter(function (mk) { return mk.ts !== mts; });\n      renderList();\n      return;\n    }\n    if (t.dataset.fd !== undefined) {\n      favDeletes.push(t.dataset.fd);\n      favs = favs.filter(function (f) { return f.ref !== t.dataset.fd; });\n      renderFavs();\n      return;\n    }\n    if (t.dataset.copy !== undefined) {\n      var ta = document.createElement('textarea');\n      ta.value = recapText(INIT.stats); ta.style.cssText = 'position:fixed;opacity:0;height:1px';\n      document.body.appendChild(ta); ta.focus(); ta.select();\n      var ok = false; try { ok = document.execCommand('copy'); } catch (err) {}\n      document.body.removeChild(ta);\n      t.textContent = ok ? 'Copied' : 'Select the text above to copy';\n    }\n    else if (t.dataset.r !== undefined) { range = t.dataset.r; renderStats(); }\n    else if (t.dataset.f !== undefined) { filter = t.dataset.f; renderList(); }\n    else if (t.dataset.ref !== undefined) openSheet(t.dataset.ref);\n    else if (t.dataset.s !== undefined && current) {\n      var n = +t.dataset.s, r = t.getBoundingClientRect();\n      current.stars = (e.clientX && e.clientX < r.left + r.width / 2) ? n - 0.5 : n;\n      edits[current.ref] = current.stars;\n      drawBig();\n    }\n  });\n  $('q').oninput = renderList;\n  document.addEventListener('toggle', function (e) {\n    if (e.target && e.target.classList && e.target.classList.contains('cald')) calOpen = e.target.open;\n  }, true);\n  function setHeaderOffset() {\n    var h = document.querySelector('header');\n    if (h) document.documentElement.style.setProperty('--hh', h.offsetHeight + 'px');\n  }\n  setHeaderOffset();\n  window.addEventListener('resize', setHeaderOffset);\n  $('sclose').onclick = closeSheet;\n  $('sdel').onclick = function () {\n    if (!current) return;\n    deletes.push(current.ref);\n    delete edits[current.ref];\n    log = log.filter(function (r) { return r.ref !== current.ref; });\n    closeSheet();\n  };\n  $('copy').onclick = function () {\n    var ta = $('csv');\n    ta.focus(); ta.select();\n    try { document.execCommand('copy'); } catch (e) {}\n  };\n  $('done').onclick = function () {\n    var out = { tmdbKey: $('tk').value.trim(), lb: { user: $('lbu').value.trim(), rows: lbRows(), hist: $('lbhist').checked, sheets: $('lbsheet').checked, sync: lbSyncReq }, mdel: markDeletes, fdel: favDeletes, edits: edits, deletes: deletes };\n    document.location.href = 'pebblejs://close#' + encodeURIComponent(JSON.stringify(out));\n  };\n\n  $('tk').value = INIT.tmdbKey || '';\n  function pill(id, on, onText, offText, needClass) {\n    var el = $(id);\n    el.textContent = on ? onText : offText;\n    el.className = 'pill' + (on ? ' ok' : (needClass ? ' need' : ''));\n  }\n  function updateChecklist() {\n    var gs = $('gsu');\n    pill('p_tk', !!$('tk').value.trim(), 'Added', 'Needed', true);\n    pill('p_lb', !!$('lbu').value.trim(), 'On', 'Optional', false);\n    pill('p_gs', !!(gs && gs.value.trim()), 'On', 'Optional', false);\n  }\n  document.addEventListener('input', updateChecklist);\n  $('lbu').value = INIT.lbUser || '';\n  $('lbs').textContent = INIT.seenCount ? INIT.seenCount + ' films marked as seen.' : '';\n  $('lbcsv').oninput = lbCount;\n  $('lbsync').onclick = function () { lbSyncReq = true; this.textContent = 'Will sync when you save'; };\n  updateChecklist();\n  $('tmdbsteps').open = !INIT.tmdbKey;   // first run: show the steps\n  renderFavs();\n  renderList();\n  renderStats();\n  renderCsv();\n  if (!INIT.tmdbKey) tab(3);\n})();\n</script>\n</body>\n</html>\n";
